struct ReferenceHardRules: View {
    let theme: ReferenceTheme
    @State private var selected: String?
    private let rules=[("push","Без push"),("remote","Remotes не меняются"),("config","Git config и hooks не меняются"),("tag","Теги не трогаются"),("force","Без принудительных флагов"),("foreign_refs","main и чужие ветки не двигаются"),("kaban_dir",".kaban/ только для демона")]
    var body:some View{LazyVGrid(columns:[GridItem(.flexible()),GridItem(.flexible())],spacing:4){ForEach(rules,id:\.0){rule in Button{selected=rule.0}label:{HStack(spacing:6){Image(systemName:"lock").font(.system(size:10));Text(rule.1).font(.system(size:10.5));Spacer(minLength:0);Image(systemName:"info.circle").font(.system(size:9))}.padding(.horizontal,7).padding(.vertical,5).frame(maxWidth:.infinity,alignment:.leading).background(theme.control,in:RoundedRectangle(cornerRadius:7)).foregroundStyle(theme.secondary)}.buttonStyle(.plain).popover(isPresented:Binding(get:{selected==rule.0},set:{if !$0{selected=nil}})){VStack(alignment:.leading,spacing:7){Text("\(rule.1) · \(rule.0)").font(.system(size:12,weight:.semibold));Text(rule.0=="force" ? "--force* по префиксу (в т. ч. rebase --force-rebase), -f там, где он принудительный. Исключения: grep -f, blame -f, ls-files -f. Любой clean без -n/--dry-run запрещён.":"Жёсткое правило \(rule.0) не снимается пресетом, проектом, стадией или разовым разрешением. Действует для каждого git-вызова агента.").font(.system(size:11))}.padding(14).frame(width:290)}}}}
}
